    [McpServerTool(Name = "yuki_accounting_process_journal", ReadOnly = false, Destructive = true, Idempotent = false, OpenWorld = true)]
    [Description("This call allows you to insert certain general journals. This can be very useful for recurring entries such as payroll journal entries. You can find the functional requirements for the elements in the XSD scheme. Procedure Collect the general journal entries in an XML file and submit it to our web service. The web service will validate the XML file by means of an XML scheme (XSD). In case the file will not be validated, the process will be cancelled and you will receive a notification explaining the validation errors. 1. Submit the XML file to our web service 2. Validation and process The sum of all lines has to be 0,00. If this is not the case, the entire file will be rejected. The date of the various transaction lines has to differ from one another. However, the balance of all transactions with the same date has to be 0,00 once again. It is possible to record a contact for each entry. This can be done by entering the full name and/or contact code. Status response At the end of the procedure, the web service will respond by sending the ID of the generated general journal file as a GUID string . Or in case the file could not be generated, the web service will send an error notification by means of a SOAPException. Description fields Below you can find a description of all fields. The XML scheme also consists of a description of the fields as well as which values and data types are needed. Journal: AdministrationID / AdministrationCoC Number: For domains with more administrations it is mandatory to fill in one of the two fields. Hereby you indicate in which administration you want to create general journal entries. Journal: DocumentSubject The subject of the created file Journal: JournalType In this field you indicate the different types of general journals. Possible values are \"GeneralJournal\" for a normal general journal entry; \"EndOfYearCorrection\" for an end-of-year correction and \"FiscalCorrection\" for a fiscal correction. For both end-of-year as fiscal corrections, the entry date has to be on the last day of the fiscal year. Journal: ProjectID ID of the project to which you want to allocate the document. Hereby the parameter \"ProjectCode\" is no longer necessary. However, the Medium bundle should be activated to make use of Projects. Journal: ProjectCode The code of the project to which you want to allocate the document. This parameter is only used if the parameter \"ProjectID\" is not given. However, the Medium bundle should be activated to make use of Projects. JournalEntry: ContactCode / ContactName In case you record the contact code, the software looks for an existing contact based on this code. If no contact code is recorded, the software looks for an existing contact based on the name. If no contact is found, a new contact is created. Pay attention: the name has to be identical (inclusive of spaces, dots, underscore etc). JournalEntry: EntryDate The date of the entry JournalEntry: GLAccount The code of the ledger account. A list of available ledger accounts and their corresponding codes can be found in the Chart of Accounts of your Yuki domain. JournalEntry: Amount The amount of the entry in EUR. Enter a negative amount for credit entries and a positive amount of debit entries. JournalEntry: Description The description of the entry. Descriptions are limited to 256 characters. If it is longer, the text will be shortened. This call creates or changes data in Yuki.")]
    public static async System.Threading.Tasks.Task<string> ProcessJournal(
        YukiSessionManager sessionManager,
        AccountingSoapClient client,
        string administrationID,
        [Description("a well-formed XML document (as a string), per the Yuki XSD for this call")] string xmlDoc)
    {
        var result = await sessionManager.ExecuteAsync(sessionId => client.ProcessJournalAsync(sessionId, administrationID, YukiXml.Parse(xmlDoc, nameof(xmlDoc))));
        return YukiResult.Format(result);
    }

